// Generates the test pages of the site from the Maester native tests (tests/**/Test.<ID>.ps1 + Test.<ID>.md).
//
// Test metadata is read from website/src/data/test-catalog.json, a JSON export of Get-MtTest that
// scripts/export-catalog.mjs refreshes (build/docs/Export-MtTestCatalogForDocs.ps1). The pages are written to
// website/.generated/tests/, which git ignores; the site's content loader (src/lib/content-loader.ts) runs this
// script at the start of every build. Usage (from website/):
//   node scripts/generate-test-docs.mjs [--catalog <path/to/test-catalog.json>] [--update-aliases]

import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { computeContributorData, snapshotPath } from "./contributors.mjs";
import { tagGroupFor, tagGroupNames } from "./tag-groups.mjs";
import { summarize } from "../src/lib/summary.mjs";

const scriptDir = dirname(fileURLToPath(import.meta.url));
const websiteRoot = join(scriptDir, "..");
const repoRoot = join(websiteRoot, "..");
const docsTestsRoot = join(websiteRoot, ".generated", "tests");
const docsCommandsRoot = join(websiteRoot, "docs", "commands");
const defaultCatalogPath = join(websiteRoot, "src", "data", "test-catalog.json");
const versionsPath = join(websiteRoot, "src", "data", "versions.json");
const sourceBaseUrl = "https://github.com/maester365/maester/blob/main/";
const generatedMarker = "<!-- This file is generated by website/scripts/generate-test-docs.mjs. Do not edit manually. -->";
const checkMode = false;

const suiteConfig = {
  maester: {
    label: "Maester",
    title: "Maester Tests",
    sidebarLabel: "🔥 Maester",
    description: "Maester security tests for Microsoft 365 and Microsoft Entra configurations.",
    overview:
      "These tests are maintained by the Maester community and validate Microsoft 365, Microsoft Entra, Defender, Intune, and related security configurations.",
  },
  eidsca: {
    label: "Entra ID SCA",
    title: "Entra ID Security Config Analyzer Tests",
    sidebarLabel: "🛡️ Entra ID SCA",
    description: "Entra ID Security Config Analyzer tests mapped to Microsoft Entra security configuration checks.",
    overview:
      "These tests are based on the Entra ID Security Config Analyzer and verify Microsoft Entra mitigations for common identity attack scenarios. They are generated from the EIDSCA config; the [EIDSCA sync page](/eidsca-sync) shows how and compares Maester with it.",
  },
  cisa: {
    label: "CISA",
    title: "CISA Tests",
    sidebarLabel: "🦅 CISA",
    description: "CISA SCuBA baseline tests for Microsoft 365 security configurations.",
    overview:
      "These tests verify Microsoft 365 tenant configuration against CISA Secure Cloud Business Applications baseline guidance.",
  },
  asd: {
    label: "ASD",
    title: "ASD Essential Eight and ISM Tests",
    sidebarLabel: "🇦🇺 ASD Essential Eight",
    description: "ASD Essential Eight requirements and Information security manual (ISM) controls implemented as Maester tests.",
    overview:
      "These tests verify Microsoft 365 tenant configuration against the [Essential Eight](https://www.cyber.gov.au/business-government/asds-cyber-security-frameworks/essential-eight) and the [Information security manual (ISM)](https://www.cyber.gov.au/business-government/asds-cyber-security-frameworks/ism), both published by the Australian Signals Directorate (ASD). You may know them as the ACSC Essential Eight and the ACSC ISM: the Australian Cyber Security Centre (ACSC) is part of ASD. The Essential Eight maturity model (November 2023) sets requirements at Maturity Level One to Three, and ASD maps each requirement to an ISM control, so each test is named after the ISM control it checks: ASD.ISM-1504 checks ISM-1504. A few tests check ISM controls outside the Essential Eight, such as ASD.ISM-1403.",
  },
  cis: {
    label: "CIS",
    title: "CIS Benchmark Tests",
    sidebarLabel: "🌀 CIS",
    description: "CIS Benchmark controls implemented as Maester tests.",
    overview:
      "These tests verify tenant and organization configuration against CIS Benchmark recommendations.",
  },
  orca: {
    label: "ORCA",
    title: "ORCA Exchange Online Tests",
    sidebarLabel: "🐋 ORCA",
    description: "ORCA Exchange Online security configuration tests included in Maester.",
    overview: "These tests validate Exchange Online security configuration checks from ORCA.",
  },
  ad: {
    label: "Active Directory",
    title: "Active Directory Tests",
    sidebarLabel: "🔑 Active Directory",
    description: "Active Directory inventory and security configuration tests for on-premises domains.",
    overview:
}

const join = (...parts: string[]) => parts.filter(Boolean).join('/');
const isTest = (id: string) => id === 'docs/tests' || id.startsWith('docs/tests/');
const isArchive = (id: string) => id === 'docs/2.x' || id.startsWith('docs/2.x/');

const sources: { owns: Owns; loader: Loader }[] = [
	{
		// Starlight's 404 page uses the entry with the id 404.
		owns: (id) => id === '404',
		loader: glob({ pattern: '404.md', base: './src/content', generateId: () => '404' }),
	},
	{
		owns: (id) => id.startsWith('docs/') && !isTest(id) && !isArchive(id),
		loader: glob({
			pattern: ['**/*.{md,mdx}'],
			base: './docs',
			generateId: ({ entry }) => join('docs', pathId(entry)),
		}),
	},
	{
		owns: isTest,
		loader: glob({
			pattern: ['**/*.{md,mdx}'],
			base: './.generated/tests',
			generateId: ({ entry, data }) => (typeof data.slug === 'string' ? data.slug : join('docs/tests', pathId(entry))),
		}),
	},
	{
		owns: isArchive,
		loader: glob({
			pattern: ['**/*.{md,mdx}'],
			base: './versioned_docs/version-2.3.0',
			generateId: ({ entry }) => join('docs/2.x', pathId(entry)),
		}),
	},
];

export function maesterLoader(): Loader {
	return {
		name: 'maester-content',
		async load(context) {
			// The test pages are written from src/data/test-catalog.json before they are loaded.
			execFileSync(process.execPath, ['scripts/generate-test-docs.mjs'], { stdio: 'inherit' });
			for (const { owns, loader } of sources) await loader.load(scoped(context, owns));
		},
	};
}
