import {
  createContext,
  type MouseEvent,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react"

type ReportLocation = { pathname: string; hash: string }
type Destination = string | { pathname: string; hash?: string }
type NavigateOptions = { replace?: boolean }

interface RouterContextValue {
  location: ReportLocation
  navigate: (destination: Destination, options?: NavigateOptions) => void
}

const RouterContext = createContext<RouterContextValue | null>(null)

function readLocation(): ReportLocation {
  const route = window.location.hash.slice(1) || "/"
  const anchorIndex = route.indexOf("#")
  const pathname = anchorIndex === -1 ? route : route.slice(0, anchorIndex)
  const hash = anchorIndex === -1 ? "" : route.slice(anchorIndex)
  return { pathname: pathname.startsWith("/") ? pathname : `/${pathname}`, hash }
}

export function HashRouter({ children }: { children: ReactNode }) {
  const [location, setLocation] = useState(readLocation)

  useEffect(() => {
    const handleHashChange = () => setLocation(readLocation())
    window.addEventListener("hashchange", handleHashChange)
    return () => window.removeEventListener("hashchange", handleHashChange)
  }, [])

  const navigate = useCallback((destination: Destination, options?: NavigateOptions) => {
    const next = typeof destination === "string" ? destination : `${destination.pathname}${destination.hash || ""}`
    const normalized = next.startsWith("/") ? next : `/${next}`

    if (options?.replace) {
      window.history.replaceState(null, "", `${window.location.pathname}${window.location.search}#${normalized}`)
      setLocation(readLocation())
    } else {
      window.location.hash = normalized
    }
  }, [])

  const value = useMemo(() => ({ location, navigate }), [location, navigate])
  return <RouterContext.Provider value={value}>{children}</RouterContext.Provider>
}

function useRouter() {
  const context = useContext(RouterContext)
  if (!context) throw new Error("Router hooks must be used within HashRouter")
  return context
}

export function useLocation() {
  return useRouter().location
}

export function useNavigate() {
  return useRouter().navigate
}

export function Link({ to, onClick, children, ...props }: Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "href"> & { to: string }) {
  const navigate = useNavigate()
  const handleClick = (event: MouseEvent<HTMLAnchorElement>) => {
    onClick?.(event)
    if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return
    event.preventDefault()
    navigate(to)
  }

  return <a href={`#${to}`} onClick={handleClick} {...props}>{children}</a>
}

// The views the sidebar lists. Each is listed only when it has something to show, so a run of one test gets a
// short sidebar and a full run gets every product, framework and pack. A pack's view is built from its rows'
// Fields (ZTA: Pillar, Category), so a new pack needs no code here.

import { frameworkLabel, frameworkTally, tally, type Model, type Row } from "@/lib/model"
import type { IconName } from "./ui"

export interface ViewDef {
  path: string
  group: "Tenants" | "Summary" | "Products" | "Frameworks" | "Packs" | "Reports"
  title: string
  product?: string
  code?: string
  icon?: IconName
  count?: number
  bad?: boolean
}

// A product, framework or pack none of whose tests ran (every one skipped or not run) has nothing to show.
const ran = (rows: Row[]) => rows.some((t) => t.Result !== "Skipped" && t.Result !== "NotRun")

export function buildViews(model: Model, extra: { affectedObjects: boolean; attachments: { title: string; path: string }[]; tenants?: number }): ViewDef[] {
  const views: ViewDef[] = []
  // A merged result of several tenants starts with the page that compares them; the sidebar lists the tenants under it.
  if (extra.tenants && extra.tenants > 1) views.push({ path: "/tenants", group: "Tenants", title: "All tenants", icon: "tenant", count: extra.tenants })
  const focused = model.focused
  // Summary: the pages that cover the whole run, so the action plan, changes and affected objects are never below
  // a long list of products.
  views.push({ path: "/", group: "Summary", title: focused ? (model.rows.length === 1 ? "Result" : "Results") : "Overview", icon: "home" })
  if (model.failing.length >= 2) views.push({ path: "/plan", group: "Summary", title: "Action plan", icon: "fix", count: model.failing.length, bad: true })
  if (!focused) views.push({ path: "/tests", group: "Summary", title: "All tests", icon: "result", count: model.rows.length })
  if (!focused && model.previous && model.changes.newlyFailing.length + model.changes.fixed.length > 0) {
    views.push({ path: "/changes", group: "Summary", title: "Changes since last run", icon: "history", count: model.changes.newlyFailing.length, bad: true })
  }
  if (extra.affectedObjects) views.push({ path: "/affected-objects", group: "Summary", title: "Affected objects", icon: "resource" })
  if (!focused) {
    for (const p of model.products) if (ran(p.rows)) views.push({ path: `/product/${encodeURIComponent(p.key)}`, group: "Products", title: p.name, product: p.key, count: tally(p.rows).Failed, bad: true })
    for (const f of model.frameworks) views.push({ path: `/framework/${encodeURIComponent(f.Key)}`, group: "Frameworks", title: frameworkLabel(f), icon: "framework", count: frameworkTally(model, f).Failed, bad: true })
    if (model.rows.some((t) => t.Mitre.length)) views.push({ path: "/attack", group: "Frameworks", title: "MITRE ATT&CK", icon: "attack" })
  }
  for (const p of model.packs) views.push({ path: `/pack/${encodeURIComponent(p.Id)}`, group: "Packs", title: p.Name, code: p.Code, count: tally(p.rows).Failed, bad: true })
  for (const a of extra.attachments) views.push({ path: a.path, group: "Reports", title: a.title, icon: "report" })
  views.push({ path: "/run", group: "Reports", title: "Run details", icon: "duration" })
  return views
}
// The ATT&CK techniques the tests help defend against, by tactic, coloured by how their tests did.

import { TACTICS, tally, type Row } from "@/lib/model"
import { useReport } from "@/components/report/ReportContext"
import { Footer } from "@/components/report/lists"

export default function AttackPage() {
  const { model, explore } = useReport()
  const byTechnique = new Map<string, Row[]>()
  for (const t of model.rows) for (const m of t.Mitre) { if (!byTechnique.has(m)) byTechnique.set(m, []); byTechnique.get(m)!.push(t) }
  const state = (rows: Row[]) => { const c = tally(rows); return c.Failed && !c.Passed ? "fail" : c.Failed ? "part" : c.Passed ? "pass" : "none" }
  const columns = TACTICS.map(([id, name]) => ({ id, name, techniques: [...byTechnique.keys()].filter((k) => model.technique(k).Tactics.includes(id)).sort((a, b) => tally(byTechnique.get(b)!).Failed - tally(byTechnique.get(a)!).Failed) })).filter((c) => c.techniques.length)
  const failing = [...byTechnique.values()].filter((rows) => tally(rows).Failed).length
  return (
    <div className="mt-wrap">
      <div className="mt-head">
        <div className="mt-eyebrow">Threats{model.attackVersion ? ` · ATT&CK ${model.attackVersion}` : ""}</div>
        <h1 className="mt-h1">{failing} of {byTechnique.size} techniques have a failing defence</h1>
        <p className="mt-lead">Each tile is a technique a Maester test helps defend against. Red means every test for it failed, amber means some did. Choose a tile to list its tests.</p>
      </div>
      <div className="mt-legend"><span><i style={{ background: "var(--mt-fail)" }} />All tests failed</span><span><i style={{ background: "var(--mt-warn)" }} />Some failed</span><span><i style={{ background: "var(--mt-pass)" }} />All passed</span><span><i style={{ background: "var(--mt-skip)" }} />Not run</span></div>
      <div className="mt-attack">
        {columns.map((col) => (
          <div key={col.id} className="mt-tac">
            <h6>{col.name}<span>{col.id} · {col.techniques.length}</span></h6>
            {col.techniques.map((k) => {
              const rows = byTechnique.get(k)!
              return (
                <button key={k} type="button" className={`mt-tech ${state(rows)}`} title={`${rows.length} tests`} onClick={() => explore({ q: k })}>
                  <span className="id">{k} · {tally(rows).Failed}/{rows.length}</span>{model.technique(k).Name}
                </button>
              )
            })}
          </div>
        ))}
      </div>
      <Footer />
    </div>
  )
}
// One framework, counted by requirement: met when every test for it passes, not met when one fails, and
// "no Maester test" for a requirement of the catalogue that no test checks.

import { useState } from "react"
